import{_ as s,o as a,c as i,ag as d}from"./chunks/framework.DoUXNnsN.js";const c=JSON.parse('{"title":"Modbus数据模型与地址","description":"","frontmatter":{"title":"Modbus数据模型与地址","aliases":["Modbus寄存器","Modbus地址","保持寄存器","输入寄存器","线圈","字节序"],"tags":["工业通信","Modbus"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Modbus","https://www.simplymodbus.ca/FC03.htm","https://www.simplymodbus.ca/FC05.htm","https://docs.chipkin.com/articles/modbus-data-types-byte-order-reference/","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":2},"headers":[],"relativePath":"70-工业通信与自动化/Modbus/Modbus数据模型与地址.md","filePath":"70-工业通信与自动化/Modbus/Modbus数据模型与地址.md"}'),e={name:"70-工业通信与自动化/Modbus/Modbus数据模型与地址.md"};function o(r,t,h,l,n,p){return a(),i("div",null,[...t[0]||(t[0]=[d(`<blockquote><p>本篇是 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 入门路径的第 2 篇。读完你应该能：说清四种数据表各自存什么；把&quot;40108&quot;这种编号换算成线上要写的地址；把寄存器里的数字还原成温度、计数、浮点数；知道 32 位数据为什么会读成乱码。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Modbus 把设备内部的数据抽象成<strong>四张表</strong>，每张表是一长串编号的格子；主站读写数据，就是按&quot;哪张表、从第几格开始、读写几格&quot;来说话。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a>：看得懂 <code>0x00C8</code> 就是 200。</li><li>看过 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 总览里的&quot;一次完整通信&quot;例子。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>主站和从站事先并不知道对方内部长什么样。Modbus 规定了一个所有设备都认的&quot;数据摆放方式&quot;：不管设备是温控器还是变频器，对外都只暴露这四张表。主站只要会&quot;读第几号格子&quot;，就能读任何设备。至于格子里装的是什么，由设备手册说明。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="四张数据表" tabindex="-1">四张数据表 <a class="header-anchor" href="#四张数据表" aria-label="Permalink to &quot;四张数据表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据表</th><th>一格的大小</th><th>主站能做什么</th><th>典型用途</th></tr></thead><tbody><tr><td>离散输入（Discrete Input）</td><td>1 位（0 或 1）</td><td>只读</td><td>读开关、按钮、传感器的通/断</td></tr><tr><td>线圈（Coil）</td><td>1 位</td><td>读和写</td><td>控制继电器、指示灯、启停</td></tr><tr><td>输入寄存器（Input Register）</td><td>16 位（0–65535）</td><td>只读</td><td>读测量值和状态，如温度、转速</td></tr><tr><td>保持寄存器（Holding Register）</td><td>16 位</td><td>读和写</td><td>读写设定值和配置，如目标温度</td></tr></tbody></table><p>每张表有 65536 个格子可寻址（地址 0 到 65535）。记忆窍门：<strong>&quot;输入&quot;是设备测出来给你看的，只读；&quot;输出/保持&quot;是你可以改的。</strong></p><p><strong>两个容易误会的点</strong>：</p><ul><li>四张表的编号是<strong>各自独立</strong>的。线圈 0 和保持寄存器 0 是两个不同的东西。</li><li>设备内部是否真的把它们放在不同的内存里，由设备厂家决定：有的设备把同一块数据同时映射到输入寄存器和保持寄存器，这样用功能码 03 或 04 读都行。这就是为什么总览里说&quot;读不到时换个功能码试试&quot;。</li></ul><h3 id="地址-线上从-0-开始-手册常从-1-开始" tabindex="-1">地址：线上从 0 开始，手册常从 1 开始 <a class="header-anchor" href="#地址-线上从-0-开始-手册常从-1-开始" aria-label="Permalink to &quot;地址：线上从 0 开始，手册常从 1 开始&quot;">​</a></h3><p>线上（报文里）的地址是 0 到 65535，<strong>从 0 开始</strong>。但很多设备手册和软件习惯用一套&quot;参考编号&quot;，<strong>从 1 开始</strong>，并用第一位数字表示是哪张表：</p><table tabindex="0"><thead><tr><th>数据表</th><th>常见参考编号起点</th><th>线上地址 = 参考编号 − 起点</th></tr></thead><tbody><tr><td>线圈</td><td>00001</td><td>编号 − 1</td></tr><tr><td>离散输入</td><td>10001</td><td>编号 − 10001</td></tr><tr><td>输入寄存器</td><td>30001</td><td>编号 − 30001</td></tr><tr><td>保持寄存器</td><td>40001</td><td>编号 − 40001</td></tr></tbody></table><p>这是行业习惯，<strong>不是协议规定的</strong>，所以不同厂家的写法并不统一（有的用 6 位的 400001），一律以设备手册为准。</p><p>两个已验证的例子（来自 simplymodbus.ca）：</p><ul><li>&quot;寄存器 40108&quot;：40108 − 40001 = 107 = 十六进制 <code>0x006B</code>，所以请求里起始地址写 <code>00 6B</code>。</li><li>&quot;线圈 #173&quot;：线上地址是 172 = <code>0xAC</code>，所以请求里写 <code>00 AC</code>。</li></ul><p><strong>最常见的错误</strong>：把 40108 直接当 40108 发出去（超出范围，得到异常码 2），或者少减了 1 导致读到邻居寄存器的值。有的软件的界面里写&quot;地址从 0 开始/从 1 开始&quot;的选项，就是为了这个差 1。</p><h3 id="一个寄存器里的-16-位怎么解释" tabindex="-1">一个寄存器里的 16 位怎么解释 <a class="header-anchor" href="#一个寄存器里的-16-位怎么解释" aria-label="Permalink to &quot;一个寄存器里的 16 位怎么解释&quot;">​</a></h3><p>寄存器只是一个 0–65535 的数，<strong>怎么解释由设备手册规定</strong>。常见的几种：</p><ol><li><strong>无符号整数</strong>：直接就是 0–65535。例如 <code>0x00FA</code> = 250。</li><li><strong>有符号整数</strong>：用补码表示负数。同一个 <code>0xFFFF</code>，无符号读是 65535，有符号读是 −1。</li><li><strong>带比例系数的整数</strong>：设备常用整数代替小数。手册写&quot;温度，单位 0.1 ℃&quot;，读到 250 就是 25.0 ℃。Python 里：<code>250 * 0.1</code> 得 <code>25.0</code>。</li><li><strong>按位表示状态</strong>：一个寄存器的 16 位各管一个开关，例如第 0 位 = 运行，第 1 位 = 故障。用 <code>value &amp; 1</code> 判断运行，<code>(value &gt;&gt; 1) &amp; 1</code> 判断故障。</li><li><strong>文本</strong>：一个寄存器放两个 ASCII 字符，几个寄存器连起来是一串文字（如设备型号）。</li></ol><h3 id="_32-位数据-占两个寄存器-顺序是最大的坑" tabindex="-1">32 位数据：占两个寄存器，顺序是最大的坑 <a class="header-anchor" href="#_32-位数据-占两个寄存器-顺序是最大的坑" aria-label="Permalink to &quot;32 位数据：占两个寄存器，顺序是最大的坑&quot;">​</a></h3><p>寄存器只有 16 位，装不下 32 位整数或浮点数，设备就用<strong>相邻两个寄存器</strong>拼成一个。<strong>Modbus 规范只规定了单个寄存器内部是&quot;高字节在前&quot;</strong>（所谓大端），<strong>没有规定两个寄存器谁在前</strong>，各厂家做法不同。</p><p>用浮点数 25.5 做例子。按 IEEE 754 单精度，25.5 的 4 个字节是 <code>41 CC 00 00</code>（依次叫 A B C D）。不同厂家的存法：</p><table tabindex="0"><thead><tr><th>名称</th><th>字节顺序</th><th>寄存器 1</th><th>寄存器 2</th><th>说明</th></tr></thead><tbody><tr><td>ABCD</td><td>A B C D</td><td><code>41CC</code></td><td><code>0000</code></td><td>最常见，高位寄存器在前</td></tr><tr><td>CDAB</td><td>C D A B</td><td><code>0000</code></td><td><code>41CC</code></td><td>交换两个寄存器（字交换）</td></tr><tr><td>BADC</td><td>B A D C</td><td><code>CC41</code></td><td><code>0000</code></td><td>每个寄存器内字节交换</td></tr><tr><td>DCBA</td><td>D C B A</td><td><code>0000</code></td><td><code>CC41</code></td><td>全部倒过来</td></tr></tbody></table><p>如果设备其实是 CDAB，而你按 ABCD 去解，读到的两个寄存器是 <code>0000</code>、<code>41CC</code>，会被解成 <code>0x000041CC</code>，换成浮点数就是 2.36×10⁻⁴¹——一个极小的数，看上去像&quot;读到 0&quot;。</p><p>不要猜，用已知值验证：找一个读数已知的量（例如把设备设置成 25.5，或者看设备屏幕上的数字），读出寄存器，挨个试四种顺序，哪个对得上就是哪个。</p><p>下面这段代码我已实际运行过，能把两个寄存器还原成浮点数：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> struct</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> regs_to_float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(r0, r1, word_swap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> word_swap:                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设备是 CDAB 时，先把两个寄存器对调</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        r0, r1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> r1, r0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> struct.unpack(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;f&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, struct.pack(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;HH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, r0, r1))[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(regs_to_float(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">41CC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ABCD 设备 -&gt; 25.5</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(regs_to_float(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">41CC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CDAB 设备 -&gt; 25.5</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(regs_to_float(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">41CC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 顺序用错了 -&gt; 2.36e-41</span></span></code></pre></div><p>有符号整数也用同样的办法：<code>struct.unpack(&quot;&gt;h&quot;, struct.pack(&quot;&gt;H&quot;, 0xFFFF))[0]</code> 得到 <code>-1</code>。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与办法</th></tr></thead><tbody><tr><td>读到的数比预期小/大 10 倍、100 倍</td><td>忘了乘比例系数，查手册的&quot;倍率/单位&quot;</td></tr><tr><td>浮点数读成极小数或巨大数</td><td>字序不对，用上面的方法逐一试 ABCD/CDAB/BADC/DCBA</td></tr><tr><td>整数应该是负数却读成很大的正数</td><td>该按有符号解释，用补码转换</td></tr><tr><td>读相邻两个寄存器，值互相错位</td><td>&quot;40001&quot;编号和线上地址差 1</td></tr><tr><td>写入 <code>70000</code> 报错</td><td>寄存器只有 16 位，最大 65535；超过要拆成两个寄存器，或者检查比例系数</td></tr><tr><td>设备手册给的是十六进制地址，换算后还是不对</td><td>弄清手册写的是&quot;线上地址&quot;还是&quot;参考编号&quot;，有的手册两种混用</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>手册写&quot;保持寄存器 40050，目标温度，单位 0.1 ℃&quot;。读它时请求里的起始地址是多少？读回 <code>0x0118</code> 是多少摄氏度？ <strong>答</strong>：40050 − 40001 = 49 = <code>0x0031</code>；<code>0x0118</code> = 280，乘 0.1 得 28.0 ℃。</li><li>一个寄存器读到 <code>0xFFF6</code>，按有符号 16 位整数是多少？ <strong>答</strong>：0xFFF6 = 65526，减 65536 得 −10。</li><li>设备把 25.5 按 BADC 存放，两个寄存器应该是什么？ <strong>答</strong>：<code>CC41</code>、<code>0000</code>（见上表）。</li><li>一台设备的状态寄存器读到 <code>0x0005</code>，二进制是 0000 0000 0000 0101，第 0 位和第 2 位是 1。如果手册规定第 0 位是&quot;运行&quot;，第 1 位是&quot;故障&quot;，设备现在是什么状态？ <strong>答</strong>：第 0 位为 1，运行；第 1 位为 0，没有故障；第 2 位为 1，要看手册里第 2 位的定义。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四张表：离散输入、线圈、输入寄存器、保持寄存器，编号各自独立。</li><li>线上地址从 0 开始，&quot;40001&quot;这类参考编号从 1 开始，换算时减去起点；不同厂家写法不一，听手册的。</li><li>寄存器里是什么含义靠手册：整数、有符号数、带倍率的整数、按位状态、文本。</li><li>32 位数据占两个寄存器，字序没有统一规定，用已知值验证。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-RTU">Modbus-RTU</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a>、<a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>各种数据类型的字节序对照：<a href="https://docs.chipkin.com/articles/modbus-data-types-byte-order-reference/" target="_blank" rel="noreferrer">https://docs.chipkin.com/articles/modbus-data-types-byte-order-reference/</a></li><li>Simply Modbus 读保持寄存器页（含地址换算例子）：<a href="https://www.simplymodbus.ca/FC03.htm" target="_blank" rel="noreferrer">https://www.simplymodbus.ca/FC03.htm</a></li></ul>`,42)])])}const u=s(e,[["render",o]]);export{c as __pageData,u as default};
